function makeReader() {
  let count = 0;
  const message = 'count=' + count;
  return {
    increment() { count++; },
    current() { return count; },
    snapshot() { return message; },
  };
}
const reader = makeReader();
reader.increment();
console.log(reader.current(), reader.snapshot());

